CREATE TABLE IF NOT EXISTS "fa_shop_schema_migration" (
  "version" varchar(64) NOT NULL,
  "description" varchar(255) NOT NULL DEFAULT '',
  "applied_at" bigint NOT NULL,
  PRIMARY KEY ("version")
);


CREATE TABLE IF NOT EXISTS "fa_shop_goods_ext" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "goods_id" int NOT NULL,
  "product_type" varchar(255) NOT NULL DEFAULT 'NORMAL',
  "composition_json" json DEFAULT NULL,
  "allergen_tags_json" json DEFAULT NULL,
  "applicable_tags_json" json DEFAULT NULL,
  "origin" varchar(255) NOT NULL DEFAULT '',
  "storage_condition" varchar(255) NOT NULL DEFAULT '',
  "shelf_life_days" int NOT NULL DEFAULT '0',
  "delivery_scope_type" varchar(255) NOT NULL DEFAULT 'SUPPLIER',
  "createtime" bigint DEFAULT NULL,
  "updatetime" bigint DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "fa_shop_goods_ext_uk_goods_id" UNIQUE ("goods_id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_sku_ext" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "goods_id" int NOT NULL,
  "goods_sku_id" int NOT NULL DEFAULT '0',
  "barcode" varchar(100) NOT NULL DEFAULT '',
  "unit" varchar(30) NOT NULL DEFAULT '份',
  "net_quantity" numeric(14,3) NOT NULL DEFAULT '0.000',
  "net_unit" varchar(20) NOT NULL DEFAULT 'g',
  "reference_cost_price" numeric(12,2) NOT NULL DEFAULT '0.00',
  "safety_stock" int NOT NULL DEFAULT '0',
  "batch_enabled" smallint NOT NULL DEFAULT '0',
  "expiry_enabled" smallint NOT NULL DEFAULT '0',
  "createtime" bigint DEFAULT NULL,
  "updatetime" bigint DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "fa_shop_sku_ext_uk_goods_sku" UNIQUE ("goods_id", "goods_sku_id")
);
CREATE INDEX IF NOT EXISTS "fa_shop_sku_ext_idx_barcode" ON "fa_shop_sku_ext" ("barcode");

CREATE TABLE IF NOT EXISTS "fa_shop_ingredient" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "code" varchar(64) NOT NULL,
  "name" varchar(100) NOT NULL,
  "category" varchar(100) NOT NULL DEFAULT '',
  "default_unit" varchar(20) NOT NULL DEFAULT 'g',
  "aliases_json" json DEFAULT NULL,
  "status" varchar(255) NOT NULL DEFAULT 'normal',
  "createtime" bigint DEFAULT NULL,
  "updatetime" bigint DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "fa_shop_ingredient_uk_code" UNIQUE ("code")
);
CREATE INDEX IF NOT EXISTS "fa_shop_ingredient_idx_name" ON "fa_shop_ingredient" ("name");

CREATE TABLE IF NOT EXISTS "fa_shop_ingredient_product_map" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "ingredient_id" int NOT NULL,
  "goods_id" int NOT NULL,
  "goods_sku_id" int NOT NULL DEFAULT '0',
  "content_quantity" numeric(14,3) NOT NULL DEFAULT '0.000',
  "content_unit" varchar(20) NOT NULL DEFAULT 'g',
  "conversion_rate" numeric(18,6) NOT NULL DEFAULT '1.000000',
  "priority" int NOT NULL DEFAULT '0',
  "is_substitute" smallint NOT NULL DEFAULT '0',
  "status" varchar(255) NOT NULL DEFAULT 'normal',
  "createtime" bigint DEFAULT NULL,
  "updatetime" bigint DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "fa_shop_ingredient_product_map_uk_ingredient_goods_sku" UNIQUE ("ingredient_id", "goods_id", "goods_sku_id")
);
CREATE INDEX IF NOT EXISTS "fa_shop_ingredient_product_map_idx_goods_sku" ON "fa_shop_ingredient_product_map" ("goods_id", "goods_sku_id");

CREATE TABLE IF NOT EXISTS "fa_shop_goods_substitute" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "goods_id" int NOT NULL,
  "goods_sku_id" int NOT NULL DEFAULT '0',
  "substitute_goods_id" int NOT NULL,
  "substitute_goods_sku_id" int NOT NULL DEFAULT '0',
  "priority" int NOT NULL DEFAULT '0',
  "status" varchar(255) NOT NULL DEFAULT 'normal',
  "createtime" bigint DEFAULT NULL,
  "updatetime" bigint DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "fa_shop_goods_substitute_uk_goods_substitute" UNIQUE ("goods_id", "goods_sku_id", "substitute_goods_id", "substitute_goods_sku_id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_supplier" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "code" varchar(64) NOT NULL,
  "name" varchar(150) NOT NULL,
  "company_name" varchar(200) NOT NULL DEFAULT '',
  "contact_name" varchar(60) NOT NULL DEFAULT '',
  "contact_mobile" varchar(30) NOT NULL DEFAULT '',
  "fulfillment_mode" varchar(255) NOT NULL DEFAULT 'SUPPLIER_DIRECT',
  "settlement_mode" varchar(50) NOT NULL DEFAULT '',
  "api_type" varchar(255) NOT NULL DEFAULT 'MANUAL',
  "api_config_encrypted" text,
  "priority" int NOT NULL DEFAULT '0',
  "status" varchar(255) NOT NULL DEFAULT 'normal',
  "createtime" bigint DEFAULT NULL,
  "updatetime" bigint DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "fa_shop_supplier_uk_code" UNIQUE ("code")
);
CREATE INDEX IF NOT EXISTS "fa_shop_supplier_idx_status_priority" ON "fa_shop_supplier" ("status", "priority");

CREATE TABLE IF NOT EXISTS "fa_shop_supplier_sku" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "supplier_id" int NOT NULL,
  "goods_id" int NOT NULL,
  "goods_sku_id" int NOT NULL DEFAULT '0',
  "supplier_goods_code" varchar(100) NOT NULL DEFAULT '',
  "supplier_sku_code" varchar(100) NOT NULL DEFAULT '',
  "supply_price" numeric(12,2) NOT NULL DEFAULT '0.00',
  "min_order_qty" int NOT NULL DEFAULT '1',
  "delivery_days" int NOT NULL DEFAULT '0',
  "fulfillment_mode" varchar(255) NOT NULL DEFAULT 'SUPPLIER_DIRECT',
  "priority" int NOT NULL DEFAULT '0',
  "last_sync_time" bigint DEFAULT NULL,
  "sync_status" varchar(255) NOT NULL DEFAULT 'PENDING',
  "status" varchar(255) NOT NULL DEFAULT 'normal',
  "createtime" bigint DEFAULT NULL,
  "updatetime" bigint DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "fa_shop_supplier_sku_uk_supplier_goods_sku" UNIQUE ("supplier_id", "goods_id", "goods_sku_id")
);
CREATE INDEX IF NOT EXISTS "fa_shop_supplier_sku_idx_goods_sku_status" ON "fa_shop_supplier_sku" ("goods_id", "goods_sku_id", "status");
CREATE INDEX IF NOT EXISTS "fa_shop_supplier_sku_idx_supplier_code" ON "fa_shop_supplier_sku" ("supplier_id", "supplier_sku_code");

CREATE TABLE IF NOT EXISTS "fa_shop_supplier_delivery_region" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "supplier_id" int NOT NULL,
  "province_id" int NOT NULL DEFAULT '0',
  "city_id" int NOT NULL DEFAULT '0',
  "area_id" int NOT NULL DEFAULT '0',
  "shipping_fee" numeric(12,2) NOT NULL DEFAULT '0.00',
  "free_shipping_amount" numeric(12,2) NOT NULL DEFAULT '0.00',
  "delivery_days" int NOT NULL DEFAULT '0',
  "status" varchar(255) NOT NULL DEFAULT 'normal',
  "createtime" bigint DEFAULT NULL,
  "updatetime" bigint DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "fa_shop_supplier_delivery_region_uk_supplier_region" UNIQUE ("supplier_id", "province_id", "city_id", "area_id")
);


CREATE TABLE IF NOT EXISTS "fa_shop_supplier_sync_log" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "supplier_id" int NOT NULL,
  "sync_type" varchar(255) NOT NULL,
  "biz_key" varchar(150) NOT NULL DEFAULT '',
  "request_id" varchar(100) NOT NULL DEFAULT '',
  "request_json" json DEFAULT NULL,
  "response_json" json DEFAULT NULL,
  "status" varchar(255) NOT NULL,
  "error_message" varchar(1000) NOT NULL DEFAULT '',
  "retry_count" int NOT NULL DEFAULT '0',
  "createtime" bigint NOT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "fa_shop_supplier_sync_log_idx_supplier_type_time" ON "fa_shop_supplier_sync_log" ("supplier_id", "sync_type", "createtime");
CREATE INDEX IF NOT EXISTS "fa_shop_supplier_sync_log_idx_status_time" ON "fa_shop_supplier_sync_log" ("status", "createtime");

CREATE TABLE IF NOT EXISTS "fa_shop_warehouse" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "code" varchar(64) NOT NULL,
  "name" varchar(120) NOT NULL,
  "owner_type" varchar(255) NOT NULL DEFAULT 'PLATFORM',
  "owner_id" int NOT NULL DEFAULT '0',
  "warehouse_type" varchar(255) NOT NULL DEFAULT 'PHYSICAL',
  "province_id" int NOT NULL DEFAULT '0',
  "city_id" int NOT NULL DEFAULT '0',
  "area_id" int NOT NULL DEFAULT '0',
  "address" varchar(255) NOT NULL DEFAULT '',
  "contact_name" varchar(60) NOT NULL DEFAULT '',
  "contact_mobile" varchar(30) NOT NULL DEFAULT '',
  "status" varchar(255) NOT NULL DEFAULT 'normal',
  "createtime" bigint DEFAULT NULL,
  "updatetime" bigint DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "fa_shop_warehouse_uk_code" UNIQUE ("code")
);
CREATE INDEX IF NOT EXISTS "fa_shop_warehouse_idx_owner" ON "fa_shop_warehouse" ("owner_type", "owner_id");

CREATE TABLE IF NOT EXISTS "fa_shop_warehouse_sku" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "warehouse_id" int NOT NULL,
  "supplier_id" int NOT NULL DEFAULT '0',
  "supplier_sku_id" int NOT NULL DEFAULT '0',
  "goods_id" int NOT NULL,
  "goods_sku_id" int NOT NULL DEFAULT '0',
  "on_hand_qty" int NOT NULL DEFAULT '0',
  "locked_qty" int NOT NULL DEFAULT '0',
  "unavailable_qty" int NOT NULL DEFAULT '0',
  "in_transit_qty" int NOT NULL DEFAULT '0',
  "version" int NOT NULL DEFAULT '0',
  "last_sync_time" bigint DEFAULT NULL,
  "createtime" bigint DEFAULT NULL,
  "updatetime" bigint DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "fa_shop_warehouse_sku_uk_warehouse_goods_sku" UNIQUE ("warehouse_id", "goods_id", "goods_sku_id")
);
CREATE INDEX IF NOT EXISTS "fa_shop_warehouse_sku_idx_supplier_sku" ON "fa_shop_warehouse_sku" ("supplier_id", "supplier_sku_id");
CREATE INDEX IF NOT EXISTS "fa_shop_warehouse_sku_idx_goods_sku" ON "fa_shop_warehouse_sku" ("goods_id", "goods_sku_id");

CREATE TABLE IF NOT EXISTS "fa_shop_stock_batch" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "warehouse_sku_id" bigint NOT NULL,
  "batch_no" varchar(100) NOT NULL,
  "production_date" date DEFAULT NULL,
  "expiry_date" date DEFAULT NULL,
  "cost_price" numeric(12,2) NOT NULL DEFAULT '0.00',
  "on_hand_qty" int NOT NULL DEFAULT '0',
  "locked_qty" int NOT NULL DEFAULT '0',
  "unavailable_qty" int NOT NULL DEFAULT '0',
  "status" varchar(255) NOT NULL DEFAULT 'normal',
  "createtime" bigint DEFAULT NULL,
  "updatetime" bigint DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "fa_shop_stock_batch_uk_warehouse_sku_batch" UNIQUE ("warehouse_sku_id", "batch_no")
);
