CREATE TABLE IF NOT EXISTS "fa_shop_stock_reservation" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "reservation_sn" varchar(64) NOT NULL,
  "biz_key" varchar(100) NOT NULL,
  "order_sn" varchar(50) NOT NULL DEFAULT '',
  "supplier_order_sn" varchar(64) NOT NULL DEFAULT '',
  "warehouse_sku_id" bigint NOT NULL,
  "goods_id" int NOT NULL,
  "goods_sku_id" int NOT NULL DEFAULT '0',
  "quantity" int NOT NULL,
  "status" varchar(255) NOT NULL DEFAULT 'LOCKED',
  "expiretime" bigint DEFAULT NULL,
  "released_at" bigint DEFAULT NULL,
  "deducted_at" bigint DEFAULT NULL,
  "createtime" bigint NOT NULL,
  "updatetime" bigint DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "fa_shop_stock_reservation_uk_reservation_sn" UNIQUE ("reservation_sn"),
  CONSTRAINT "fa_shop_stock_reservation_uk_biz_warehouse_sku" UNIQUE ("biz_key", "warehouse_sku_id")
);
CREATE INDEX IF NOT EXISTS "fa_shop_stock_reservation_idx_order_status" ON "fa_shop_stock_reservation" ("order_sn", "status");
CREATE INDEX IF NOT EXISTS "fa_shop_stock_reservation_idx_expire_status" ON "fa_shop_stock_reservation" ("expiretime", "status");

CREATE TABLE IF NOT EXISTS "fa_shop_stock_flow" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "flow_sn" varchar(64) NOT NULL,
  "warehouse_sku_id" bigint NOT NULL,
