  "warehouse_id" int NOT NULL,
  "goods_id" int NOT NULL,
  "goods_sku_id" int NOT NULL DEFAULT '0',
  "biz_type" varchar(40) NOT NULL,
  "biz_no" varchar(100) NOT NULL DEFAULT '',
  "change_on_hand" int NOT NULL DEFAULT '0',
  "change_locked" int NOT NULL DEFAULT '0',
  "before_on_hand" int NOT NULL,
  "after_on_hand" int NOT NULL,
  "before_locked" int NOT NULL,
  "after_locked" int NOT NULL,
  "operator_type" varchar(30) NOT NULL DEFAULT 'SYSTEM',
  "operator_id" int NOT NULL DEFAULT '0',
  "remark" varchar(500) NOT NULL DEFAULT '',
  "createtime" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "fa_shop_stock_flow_uk_flow_sn" UNIQUE ("flow_sn")
);
CREATE INDEX IF NOT EXISTS "fa_shop_stock_flow_idx_warehouse_sku_time" ON "fa_shop_stock_flow" ("warehouse_sku_id", "createtime");
CREATE INDEX IF NOT EXISTS "fa_shop_stock_flow_idx_biz" ON "fa_shop_stock_flow" ("biz_type", "biz_no");

CREATE TABLE IF NOT EXISTS "fa_shop_shopping_list" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
