  "source_hash" char(64) NOT NULL DEFAULT '',
  "status" varchar(255) NOT NULL DEFAULT 'DRAFT',
  "confirmed_at" bigint DEFAULT NULL,
  "createtime" bigint NOT NULL,
  "updatetime" bigint DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "fa_shop_shopping_list_uk_list_sn" UNIQUE ("list_sn"),
  CONSTRAINT "fa_shop_shopping_list_uk_user_menu_version" UNIQUE ("user_id", "menu_version_id", "list_version")
);
CREATE INDEX IF NOT EXISTS "fa_shop_shopping_list_idx_user_status" ON "fa_shop_shopping_list" ("user_id", "status");

CREATE TABLE IF NOT EXISTS "fa_shop_shopping_list_item" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "shopping_list_id" bigint NOT NULL,
  "ingredient_id" int NOT NULL,
  "required_quantity" numeric(14,3) NOT NULL,
