  "net_quantity" numeric(14,3) NOT NULL,
  "unit" varchar(20) NOT NULL,
  "source_refs_json" json DEFAULT NULL,
  "constraint_result_json" json DEFAULT NULL,
  "selected_goods_id" int NOT NULL DEFAULT '0',
  "selected_goods_sku_id" int NOT NULL DEFAULT '0',
  "selected_supplier_id" int NOT NULL DEFAULT '0',
  "purchase_quantity" int NOT NULL DEFAULT '0',
  "covered_quantity" numeric(14,3) NOT NULL DEFAULT '0.000',
  "shortage_quantity" numeric(14,3) NOT NULL DEFAULT '0.000',
  "excess_quantity" numeric(14,3) NOT NULL DEFAULT '0.000',
  "purchase_mode" varchar(255) NOT NULL DEFAULT 'PLATFORM',
  "substitution_confirmed" smallint NOT NULL DEFAULT '0',
  "createtime" bigint NOT NULL,
  "updatetime" bigint DEFAULT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "fa_shop_shopping_list_item_idx_list" ON "fa_shop_shopping_list_item" ("shopping_list_id");
CREATE INDEX IF NOT EXISTS "fa_shop_shopping_list_item_idx_ingredient" ON "fa_shop_shopping_list_item" ("ingredient_id");

CREATE TABLE IF NOT EXISTS "fa_shop_order_ext" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "order_id" int NOT NULL,
  "order_sn" varchar(50) NOT NULL,
  "user_id" int NOT NULL,
  "idempotency_key" varchar(100) NOT NULL,
  "shopping_list_id" bigint NOT NULL DEFAULT '0',
  "shopping_list_version" int NOT NULL DEFAULT '0',
  "biz_status" varchar(40) NOT NULL DEFAULT 'PENDING_PAYMENT',
  "fulfillment_status" varchar(40) NOT NULL DEFAULT 'PENDING',
  "refund_status" varchar(40) NOT NULL DEFAULT 'NONE',
  "trace_id" varchar(64) NOT NULL DEFAULT '',
  "version" int NOT NULL DEFAULT '0',
  "createtime" bigint NOT NULL,
  "updatetime" bigint DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "fa_shop_order_ext_uk_order_id" UNIQUE ("order_id"),
  CONSTRAINT "fa_shop_order_ext_uk_order_sn" UNIQUE ("order_sn"),
  CONSTRAINT "fa_shop_order_ext_uk_user_idempotency" UNIQUE ("user_id", "idempotency_key")
);
CREATE INDEX IF NOT EXISTS "fa_shop_order_ext_idx_user_status" ON "fa_shop_order_ext" ("user_id", "biz_status");

