  "preparing_at" bigint DEFAULT NULL,
  "shipping_at" bigint DEFAULT NULL,
  "completed_at" bigint DEFAULT NULL,
  "cancelled_at" bigint DEFAULT NULL,
  "createtime" bigint NOT NULL,
  "updatetime" bigint DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "fa_shop_order_supplier_uk_supplier_order_sn" UNIQUE ("supplier_order_sn"),
