CREATE TABLE IF NOT EXISTS "fa_shop_aftersales_ext" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "aftersales_id" int NOT NULL,
  "supplier_order_id" bigint NOT NULL,
  "supplier_id" int NOT NULL,
  "warehouse_id" int NOT NULL,
  "return_status" varchar(255) NOT NULL DEFAULT 'NONE',
  "restock_quantity" int NOT NULL DEFAULT '0',
  "idempotency_key" varchar(100) NOT NULL DEFAULT '',
  "createtime" bigint NOT NULL,
  "updatetime" bigint DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "fa_shop_aftersales_ext_uk_aftersales" UNIQUE ("aftersales_id"),
  CONSTRAINT "fa_shop_aftersales_ext_uk_supplier_idempotency" UNIQUE ("supplier_id", "idempotency_key")
);


CREATE TABLE IF NOT EXISTS "fa_shop_order_substitution" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "order_id" int NOT NULL,
  "order_goods_id" int NOT NULL,
  "from_supplier_id" int NOT NULL,
  "from_goods_id" int NOT NULL,
  "from_goods_sku_id" int NOT NULL DEFAULT '0',
  "to_supplier_id" int NOT NULL DEFAULT '0',
  "to_goods_id" int NOT NULL,
  "to_goods_sku_id" int NOT NULL DEFAULT '0',
  "constraint_result_json" json DEFAULT NULL,
  "price_difference" numeric(12,2) NOT NULL DEFAULT '0.00',
  "status" varchar(255) NOT NULL DEFAULT 'PENDING_CONFIRM',
  "confirmed_at" bigint DEFAULT NULL,
  "createtime" bigint NOT NULL,
  "updatetime" bigint DEFAULT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "fa_shop_order_substitution_idx_order_status" ON "fa_shop_order_substitution" ("order_id", "status");
CREATE INDEX IF NOT EXISTS "fa_shop_order_substitution_idx_order_goods" ON "fa_shop_order_substitution" ("order_goods_id");

